/usr/bin/bash -lc "python - <<'PY'
import io, tarfile, urllib.request
url = 'https://arxiv.org/src/1903.05032v4'
data = urllib.request.urlopen(url, timeout=30).read()
print('Downloaded bytes:', len(data))
try:
    archive = tarfile.open(fileobj=io.BytesIO(data), mode='r:*')
    for member in archive.getmembers():
        if member.name.endswith('.tex'):
            source = archive.extractfile(member).read().decode('utf-8', errors='replace')
            lines = source.splitlines()
            print('Source:', member.name, 'lines:', len(lines))
            for i, line in enumerate(lines):
                if 'silly_injectivity' in line or ('D_{' in line and 'W_i' in line) or 'metabelian_injectivity' in line:
                    for j in range(max(0, i-3), min(len(lines), i+5)):
                        print(f'{j+1}: {lines[j]}')
except tarfile.ReadError:
    print(data[:500].decode('utf-8', errors='replace'))
PY"
